  shang: { n: 'Die Shang-Dynastie', p: 'Anyang, China', d: 'Chinas erste archäologisch gesicherte Dynastie, berühmt für Bronzeguss und Orakelknochenschrift — die Wurzel der chinesischen Schrift.' },
  minoan: { n: 'Die minoische Kultur', p: 'Knossos, Kreta', d: 'Europas erste große Kultur beherrscht vom Palast von Knossos aus die Ägäis — mit lebendigen Fresken und einer bis heute unentzifferten Schrift.' },
  hammurabi: { n: 'Der Kodex Hammurapi', p: 'Babylon', d: 'Hammurapi verkündet eines der ältesten entzifferten Gesetzbücher: 282 Gesetze, gemeißelt auf einer Stele — „Auge um Auge“.' },
  bronze_collapse: { n: 'Der Kollaps der späten Bronzezeit', p: 'Östliches Mittelmeer', d: 'Innerhalb weniger Jahrzehnte stürzen die Palastwirtschaften von Mykene bis Ugarit ein — Dürre, Hungersnot, Erdbeben und die rätselhaften „Seevölker“.' },
  troy: { n: 'Der Trojanische Krieg (traditionelle Datierung)', p: 'Troja, Anatolien', d: 'Legende und Archäologie verschwimmen: ein Krieg um Helena von Troja, später von Homer verewigt — in den Jahren, als die bronzezeitliche Welt zerbrach.' },
  phoenician_alpha: { n: 'Das phönizische Alphabet', p: 'Byblos, Phönizien', d: 'Phönizische Händler schaffen ein 22-buchstabiges Konsonantenalphabet — der Urahn des Griechischen, Lateinischen, Arabischen, Hebräischen und der meisten heute gebräuchlichen Schriften.' },
