  olmec: { n: 'Die Olmekken', p: 'La Venta, Mexiko', d: 'Die „Mutterkultur“ Mesoamerikas meißelt kolossale Steinköpfe und legt Ritualmuster an, die später Maya und Azteken erben.' },
  zhou: { n: 'Die Zhou-Dynastie', p: 'Haojing, China', d: 'Chinas längste Dynastie führt das „Mandat des Himmels“ ein, während ihre späten Jahrhunderte Konfuzius, Laozi und die Hundert Schulen des Denkens hervorbringen.' },
  assyria: { n: 'Das Neuassyrische Reich', p: 'Ninive, Assyrien', d: 'Die erste echte Supermacht: Eisenheere, Massendeportationen und die große Bibliothek Assurbanipals machen Assyrien zum Herren des Nahen Ostens.' },
  new_kingdom_ramses: { n: 'Ramses II.', p: 'Theben, Ägypten', d: 'Ägyptens größter Pharao regiert 66 Jahre, kämpft bei Kadesch gegen die Hethiter und errichtet Abu Simbel.' },
