  rome_founded: { n: 'Die Gründung Roms', p: 'Rom', d: 'Traditionelles Datum der Gründung Roms durch Romulus auf dem Palatin — ein Dorf, das dereinst die Mittelmeerwelt beherrschen wird.' },
  homer: { n: 'Homer dichtet Ilias & Odyssee', p: 'Ionien (Smyrna)', d: 'Blinder Sänger oder ganze Sängertradition — wie auch immer: An der Küste Kleinasiens wird der Grundstein der abendländischen Literatur gelegt.' },
