  buddha: { n: 'Siddhartha Gautama — der Buddha', p: 'Bodh Gaya, Indien', d: 'Ein Prinz aus dem Shakya-Klan erlangt unter dem Bodhi-Baum die Erleuchtung und lehrt den Mittleren Weg — die Gründung einer der großen Weltreligionen.' },
  confucius: { n: 'Konfuzius', p: 'Qufu, China', d: 'Chinas einflussreichster Denker lehrt eine Ethik der Familienloyalität, des Ritus und des guten Regierens — seine Ideen prägen Ostasien bis heute.' },
