  dna: { n: 'Die Struktur der DNA wird entschlüsselt', p: 'Cambridge', d: 'Watson, Crick und Franklins „Photo 51“ enthüllen die Doppelhelix — der Bauplan des Lebens.' },
  cuban_crisis: { n: 'Die Kubakrise', p: 'Kuba', d: 'Dreizehn Tage am Rand des Atomkriegs — Kennedy und Chruschtschow weichen aus, dann entsteht der heiße Draht.' },
  mlk_speech: { n: '„I Have a Dream“', p: 'Washington, D.C.', d: 'Eine Viertelmillion Menschen marschieren auf Washington; von den Stufen des Lincoln Memorial tritt Kings Traum in die Geschichte ein.' },
  mlk: { n: 'Martin Luther King Jr.', p: 'Atlanta, USA', d: 'Gewaltlosigkeit als Strategie und Predigt — die mit dem Nobelpreis ausgezeichnete Stimme der Bürgerrechtsbewegung, mit 39 erschossen.' },
  vietnam_war: { n: 'Der Vietnamkrieg', p: 'Vietnam', d: 'Zwanzig Jahre Krieg enden mit Hubschraubern über dem Dach der Botschaft in Saigon — der erste im Fernsehen verlorene Krieg.' },
  apollo11: { n: 'Apollo 11 landet auf dem Mond', p: 'Cape Canaveral → Mond', d: '„Der Adler ist gelandet.“ Armstrong und Aldrin betreten eine andere Welt, während 600 Millionen zusehen — „ein gewaltiger Sprung für die Menschheit“.' },
  berlin_wall: { n: 'Der Fall der Berliner Mauer', p: 'Berlin', d: 'Eine verpatzte Pressekonferenz, dann Hämmern: Die Mauer öffnet sich, und das konkreteste Symbol des Kalten Krieges zerbröckelt.' },
  singing_revolution: { n: 'Die Singende Revolution & der Baltische Weg', p: 'Tallinn → Riga → Vilnius', d: 'Hunderttausende singen verbotene Lieder mit einer Stimme — und am 23. August 1989 fassen zwei Millionen Menschen über 675 km von Tallinn bis Vilnius an den Händen. Litauen erklärt als Erstes die Wiederherstellung (11. März 1990); bis August 1991 sind alle drei frei.' },
  www: { n: 'Das World Wide Web wird erfunden', p: 'CERN, Genf', d: 'Tim Berners-Lee liefert HTML, HTTP und den ersten Browser — und verschenkt alles umsonst.' },
  soviet_collapse: { n: 'Die Auflösung der UdSSR', p: 'Moskau', d: 'Fünfzehn Republiken, eine eingeholte Flagge: Die Sowjetunion endet am ersten Weihnachtstag 1991 — und der Kalte Krieg mit ihr.' },
  ukraine_independence: { n: 'Die Ukraine erklärt ihre Unabhängigkeit', p: 'Kyjiw', d: 'Am 24. August 1991, nachdem der Moskauer Putsch zusammengebrochen ist, erklärt die Werchowna Rada die Unabhängigkeit; am 1. Dezember bestätigen über 90 % der Wähler — mit Mehrheiten in jeder Region — per Referendum.' },
  maidan: { n: 'Euromaidan / Revolution der Würde', p: 'Kyjiw', d: 'Massenproteste brechen aus, als die Regierung das EU-Assoziierungsabkommen aussetzt; nach drei Monaten töten Scharfschützen rund hundert Demonstranten (die „Himmlische Hundert“) und der Präsident flieht — Russland antwortet mit der Besetzung der Krim und entzündet den Krieg im Donbas.' },
  stus: { n: 'Wassyl Stus', p: 'Region Winnyzja, Ukraine', d: 'Dichter und Übersetzer, der nicht widerrufen wollte: 23 Jahre seines Lebens in Gefängnissen, Lagern und Exil, gestorben 1985 im Hungerstreik in Perm-36 — posthum rehabiliert und als Nationalfigur wiederbestattet.' },
  ukraine_war: { n: 'Der russisch-ukrainische Krieg', p: 'Ukraine', d: 'Ausgehend von der Besetzung der Krim und dem verdeckten Krieg im Donbas (2014) startet Russland am 24. Februar 2022 seine groß angelegte Invasion der Ukraine — der größte Krieg in Europa seit 1945. Kyjiw hält, und der Krieg formt die Weltordnung neu.' },
  mandela_elected: { n: 'Mandela wird Präsident', p: 'Pretoria', d: 'Nach 27 Jahren als Gefangener wird Nelson Mandela in Südafrikas erster freier Wahl gewählt — und verzeiht seinen Wärtern.' },
  mandela: { n: 'Nelson Mandela', p: 'Südafrika', d: '27 Jahre auf Robben Island, dann Versöhnung statt Rache — das Gewissen einer Nation.' },
