  napoleonic_wars: { n: 'Die Napoleonischen Kriege', p: 'Europa', d: 'Ein Dutzend Jahre Kontinentalkrieg zeichnen jede Karte Europas neu — und exportieren Nationalismus und Gesetzbücher in die ganze Welt.' },
  haiti: { n: 'Die Haitianische Revolution', p: 'Saint-Domingue', d: 'Versklavte Menschen befreien sich selbst — die einzige erfolgreiche Sklavenrevolution der Geschichte schafft die erste schwarze Republik.' },
  bolivar: { n: 'Simón Bolívar', p: 'Caracas', d: 'Der Befreier macht sechs Nationen von Spanien frei — und stirbt desillusioniert: „Ich habe das Meer gepflügt.“' },
  eidsvoll: { n: 'Norwegens Verfassung von Eidsvoll', p: 'Eidsvoll, Norwegen', d: 'Am 17. Mai 1814 — heute Norwegens Nationalfeiertag — schreiben 112 Männer in Eidsvoll eine der liberalsten Verfassungen der Welt und halten die Flamme der Staatlichkeit innerhalb der Union mit Schweden am Leben.' },
  song_festival: { n: 'Das erste estnische Sängerfest', p: 'Tartu, Estland', d: 'Fast tausend Sänger versammeln sich 1869 in Tartu — der Beginn einer Chortradition, die eine Nation durch zwei Imperien in die Freiheit tragen wird.' },
  andersen: { n: 'Hans Christian Andersen', p: 'Odense, Dänemark', d: 'Der Sohn eines armen Schusters aus Odense schreibt die Kleine Meerjungfrau, das Hässliche Entlein und 150 weitere Märchen — übersetzt in mehr als 125 Sprachen.' },
  kierkegaard: { n: 'Søren Kierkegaard', p: 'Kopenhagen', d: 'Melancholischer Däne, Meister der Ironie und Vater des Existenzialismus: „Das Leben kann nur rückwärts verstanden werden — aber es muss vorwärts gelebt werden.“' },
  latin_independence: { n: 'Lateinamerikas Unabhängigkeit', p: 'Spanisch-Amerika', d: 'Von Mexiko bis Argentinien reißt sich Spanisch-Amerika in fünfzehn Kriegsjahren los.' },
  waterloo: { n: 'Die Schlacht bei Waterloo', p: 'Waterloo, Belgien', d: '„Eine der knappsten Sachen, die man je gesehen hat“ — Wellington und Blücher beenden Napoleons Hundert Tage.' },
  greek_independence: { n: 'Der Griechische Unabhängigkeitskrieg', p: 'Griechenland', d: 'Nach 400 Jahren löst sich Griechenland von der osmanischen Herrschaft — Byron stirbt in Missolonghi, und der Philhellenismus erfasst Europa.' },
  manifesto: { n: 'Das Kommunistische Manifest', p: 'London', d: 'Marx und Engels veröffentlichen im Revolutionsjahr 1848: „Ein Gespenst geht um in Europa.“' },
