  se_erik_eriksonerna: { n: 'Erik Stenkilsson & Erik Hedning — Rivalenkönige', p: 'Skara, Schweden', d: 'Zwei rivalisierende Eriks — der Stenkil-Erbe und der heidnische Anwärter — stritten um den Thron und fielen beide im selben Jahr.' },
  se_halsten: { n: 'Halsten Stenkilsson', p: 'Skara, Schweden', d: 'Ein friedlicher König zwischen zwei heidnischen Aufständen — später Miterregent seines Bruders Inge.' },
  se_hakan_rode: { n: 'Håkan Rote', p: 'Sigtuna, Schweden', d: 'Ein dunkeles Intermezzo — wohl der König der heidnischen Gegenbewegung — zwischen den Stenkil-Brüdern.' },
  se_inge_stare: { n: 'Inge der Ältere', p: 'Skara, Schweden', d: 'Wegen der Weigerung, am Upsala-Opfer teilzunehmen, vertrieben — kehrte zurück und gewann Schweden endgültig für das Christentum.' },
  se_blot_sven: { n: 'Blot-Sven', p: 'Uppsala, Schweden', d: 'Für das Versprechen der alten Opfer auf den Thron gehoben — binnen drei Jahren von Inges Hand tot.' },
