  se_ragnvald: { n: 'Ragnvald Knaphövde', p: 'Skara, Schweden', d: '„Kugelkopf“: ritt ohne Geiseln, wie der Brauch verlangte, zum Thing der Göten — unterwegs erschlagen.' },
  se_magnus_stark: { n: 'Magnus der Starke', p: 'Skara, Schweden', d: 'In Dänemark geborener Enkel Sigurd Jorsalfares — Schwedens erster Anwärter mit norwegischem Königsblut; bei Fotevik gefallen (1134).' },
  se_sverker_aldre: { n: 'Sverker I. der Ältere', p: 'Linköping, Schweden', d: 'Erster der Sverker-Linie aus Östergötland: gründete das Kloster Alvastra — von eigenem Diener auf dem Weg zur Messe ermordet (1156).' },
  se_erik_helige: { n: 'Erik IX. der Heilige', p: 'Uppsala, Schweden', d: 'Führte mit Bischof Henrik den Kreuzzug nach Finnland — am Christi-Himmelfahrts-Gottesdienst von Uppsala erschlagen; Schwedens Nationalheiliger.' },
  se_magnus_henriksson: { n: 'Magnus Henriksson', p: 'Skara, Schweden', d: 'Dänischer Statthalter, der nach Eriks Ermordung die Krone nahm — binnen eines Jahres getötet.' },
  se_karl_sverkersson: { n: 'Karl VII. Sverkersson', p: 'Visingsö, Schweden', d: 'Erstmals „König der Svear und Göten“ genannt — fiel in der Visingsö-Fehde mit den Erik-Söhnen (1167).' },
  se_knut_eriksson: { n: 'Knut I. Eriksson', p: 'Uppsala, Schweden', d: 'Baute die Erik-Dynastie: nahm Visingsö, prägte Münzen, hinterließ zwei Söhne, die Schweden krönen würde.' },
