  se_karl_x_gustav: { n: 'Karl X. Gustav', p: 'Stockholm', d: 'Führte eine Armee über die gefrorenen Belte nach Kopenhagen (1658) — Schweden am breitesten, Dänemark durch Vertrag halbiert.' },
