  se_adolf_fredrik: { n: 'Adolf Friedrich', p: 'Stockholm', d: 'Der Lübecker Bischofskönig der Hüte — starb, so die Legende, an einem Festtagsdessert.' },
  se_gustav_iii: { n: 'Gustav III.', p: 'Stockholm', d: 'Der Theaterkönig: sein Staatsstreich von 1772 stellte die Königsmacht wieder her — reformierte, fehdete, wurde auf einem Maskenball erschossen; Verdi machte eine Oper daraus.' },
  se_gustav_iv_adolf: { n: 'Gustav IV. Adolf', p: 'Stockholm', d: 'Der starrköpfige Idealist: verlor Finnland an Russland (1809) und im selben Jahr seinen Thron.' },
  se_karl_xiii: { n: 'Karl XIII.', p: 'Stockholm', d: 'Der kinderlose alte König, der einen französischen Marschall adoptierte — die Bernadotte-Linie regiert noch heute.' },
  se_karl_xiv_johan: { n: 'Karl XIV. Johan (Bernadotte)', p: 'Stockholm', d: 'Napoleonischer Marschall — Kronprinz — König: wechselte die Seiten, nahm Norwegen 1814, gründete die Dynastie.' },
  se_oskar_i: { n: 'Oskar I.', p: 'Stockholm', d: 'Der sanfte Bernadotte: liberalisierte die Union, baute Schwedens erste Eisenbahn, hielt sich aus dem Krimkrieg heraus.' },
